// Decode performUpkeep calldata for both PriceUpkeep and TradesUpkeep
const ethers = require('ethers');

// PriceUpkeep calldata
const priceUpkeepCalldata = "";

// TradesUpkeep calldata (8 trades)
const tradesUpkeepCalldata = "";

console.log("=== PRICEUPKEEP TRANSACTION ===\n");

// Decode PriceUpkeep
try {
    const decoded = ethers.utils.defaultAbiCoder.decode(
        ['bytes', 'uint256'],
        priceUpkeepCalldata
    );

    const chainlinkReport = decoded[0];
    const orderId = decoded[1].toString();

    console.log(`Order ID: ${orderId} (0x${BigInt(orderId).toString(16)})`);
    console.log(`Chainlink Report Length: ${chainlinkReport.length} bytes`);
    console.log(`Total Calldata Size: ${priceUpkeepCalldata.length / 2 - 1} bytes`);

    // Try to decode the inner report structure
    // Format: (bytes32[3], bytes) where bytes contains the actual report
    const innerDecoded = ethers.utils.defaultAbiCoder.decode(
        ['bytes32[3]', 'bytes'],
        chainlinkReport
    );

    console.log(`\nChainlink Report Structure:`);
    console.log(`- Report Context (3 x bytes32): ${innerDecoded[0].length * 32} bytes`);
    console.log(`- Report Data Length: ${innerDecoded[1].length} bytes`);

} catch (error) {
    console.log("Error decoding:", error.message);
}

console.log("\n=== TRADESUPKEEP TRANSACTION ===\n");

// Decode TradesUpkeep
try {
    const decoded = ethers.utils.defaultAbiCoder.decode(
        ['tuple(address trader, uint256 pairId, uint256 index, uint8 limitOrder)[]', 'uint256'],
        tradesUpkeepCalldata
    );

    const trades = decoded[0];
    const timestamp = decoded[1].toString();

    console.log(`Timestamp: ${timestamp} (${new Date(parseInt(timestamp) * 1000).toISOString()})`);
    console.log(`Number of Trades: ${trades.length}`);
    console.log(`Total Calldata Size: ${tradesUpkeepCalldata.length / 2 - 1} bytes`);
    console.log(`Calldata per Trade: ${(tradesUpkeepCalldata.length / 2 - 1 - 132) / trades.length} bytes\n`);

    const limitOrderTypes = ['TP', 'SL', 'LIQ', 'OPEN', 'CLOSE_DAY_TRADE'];

    // Count by type
    const typeCounts = {};
    trades.forEach(trade => {
        const orderType = limitOrderTypes[trade.limitOrder] || `UNKNOWN(${trade.limitOrder})`;
        typeCounts[orderType] = (typeCounts[orderType] || 0) + 1;
    });

    console.log("Trade Type Distribution:");
    Object.entries(typeCounts).forEach(([type, count]) => {
        console.log(`  ${type}: ${count} trades`);
    });

    console.log("\nDetailed Trade List:");
    trades.forEach((trade, i) => {
        const orderType = limitOrderTypes[trade.limitOrder] || `UNKNOWN(${trade.limitOrder})`;
        console.log(`  ${i + 1}. ${trade.trader.substring(0, 10)}... | Pair: ${trade.pairId} | Index: ${trade.index} | Type: ${orderType}`);
    });

} catch (error) {
    console.log("Error decoding:", error.message);
}

console.log("\n=== CALLDATA SIZE COMPARISON ===\n");
console.log(`PriceUpkeep:   ${priceUpkeepCalldata.length / 2 - 1} bytes`);
console.log(`TradesUpkeep:  ${tradesUpkeepCalldata.length / 2 - 1} bytes`);
console.log(`\nCalldata Cost (@ 16 gas/byte):`);
console.log(`PriceUpkeep:   ${(priceUpkeepCalldata.length / 2 - 1) * 16} gas`);
console.log(`TradesUpkeep:  ${(tradesUpkeepCalldata.length / 2 - 1) * 16} gas`);
